SELECT 
FROM dms_commission_record

    AND agent_id = #{agentId}
    AND order_no LIKE CONCAT('%', #{orderNo}, '%')
    AND status = #{status}
    AND commission_level = #{commissionLevel}
    AND bonus_type = #{bonusType}
    AND create_time >= #{startTime}
    AND create_time <= #{endTime}

ORDER BY create_time DESC, id DESC

SELECT 
FROM dms_commission_record r
WHERE r.status = 0
  AND create_time <= #{cutoffTime}
  AND create_time >= #{periodStart}
  AND create_time <= #{periodEnd}
  AND NOT EXISTS (
      SELECT 1 FROM dms_commission_settlement_item item
      INNER JOIN dms_commission_settlement_batch batch ON batch.id = item.batch_id
      WHERE item.commission_record_id = r.id AND batch.status = 0
  )
ORDER BY r.id

